function vscodeMap(s:SlideData){
 const host=h('div',{className:'vscodeMap workspaceMapInteractive'});
 let overlay:any=null,opener:any=null;
 function close(){if(!overlay)return;overlay.remove();overlay=null;opener?.focus();}
 function open(index:number,button:any){
  const detail=s.regionDetails?.[index];if(!detail)return;
  close();opener=button;const r=vscodeRegions[index];
  const closeButton:any=<button type="button" className="workspacePopupClose" aria-label={'Đóng '+r.name} onClick={close}>Đóng ×</button>;
  const panel:any=<section className="workspacePopup" role="dialog" aria-modal="true" aria-labelledby="workspace-popup-title"><header className="workspacePopupHeader"><span className="workspacePopupNumber" aria-hidden="true">{String(index+1).padStart(2,'0')}</span><div className="workspacePopupHeading"><small>VÙNG {String(index+1).padStart(2,'0')} · VS CODE</small><h2 id="workspace-popup-title">{detail.title}</h2><p>{detail.message}</p></div>{closeButton}</header>{regionDetail(detail)}</section>;
  overlay=h('div',{className:'workspacePopupOverlay'});
  overlay.addEventListener('click',(event:MouseEvent)=>{if(event.target===overlay)close();});
  overlay.addEventListener('keydown',(event:KeyboardEvent)=>{
   if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close();}
   if(event.key==='Tab'){
    const items=Array.from(panel.querySelectorAll('button,[tabindex="0"]')) as HTMLElement[];
    const first=items[0],last=items[items.length-1];
    if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
    else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
   }
  });
  overlay.append(panel);host.append(overlay);closeButton.focus();
 }
 const shot:any=<div className="vscodeShot"><img src={assets['VS Code workspace']} alt="Ảnh VS Code của dự án, với sáu vùng được đánh số và khoanh đỏ"/><svg className="vscodeMarks" viewBox="0 0 1917 1152" aria-hidden="true">{vscodeRegions.map((r,i)=><g className="vscodeRegionReveal" style={{animationName:'vscodeRegionReveal'+(i+1)}}><rect x={r.x} y={r.y} width={r.w} height={r.h} rx="14"/><circle cx={r.cx} cy={r.cy} r="29"/><text x={r.cx} y={r.cy}>{i+1}</text></g>)}</svg></div>;
 vscodeRegions.forEach((r,i)=>{const target=<button type="button" className="vscodeHotspot" aria-haspopup="dialog" aria-label={'Xem vùng '+(i+1)+': '+r.name} style={{left:r.x/1917*100+'%',top:r.y/1152*100+'%',width:r.w/1917*100+'%',height:r.h/1152*100+'%'}} onClick={()=>open(i,target)}/>;shot.append(target);});
 host.append(<style>{popupTypographyCss+workspacePopupCss}</style>,shot);
 const names=h('div',{className:'vscodeNames'});
 vscodeRegions.forEach((r,i)=>{const button=<button type="button" className="vscodeName" aria-haspopup="dialog" aria-label={'Mở chức năng vùng '+(i+1)+': '+r.name} onClick={()=>open(i,button)}><span className="vscodeBadge">{i+1}</span><div><h3>{r.name}</h3><p>{r.subtitle}</p></div></button>;names.append(button);});
 host.append(names);return host;
}


const regionDetailCss = `
.regionDetail{width:100%;display:flex;flex-direction:column;gap:16px}.regionLead{height:58px;border-radius:16px;background:linear-gradient(110deg,#123f68,#082945);display:flex;align-items:center;padding:0 24px;gap:24px;border:1px solid #b3915970}.regionLead strong{color:#e9ca8b;font-size:18px;letter-spacing:.8px;white-space:nowrap}.regionLead span{color:#edf3f7;font-size:20px}.regionGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.regionCard{position:relative;min-height:148px;padding:16px 24px 18px 30px;border:1px solid #b3915966;border-left:4px solid #b39159;border-radius:20px;background:#f7f4ed;box-shadow:0 6px 16px #08294506}.regionCard h3{margin:0 0 8px;color:#123f68;font-size:22px;line-height:1.2;font-weight:800}.regionCard p{margin:0;color:#4d6577;font-size:19px;line-height:1.4;font-weight:550}.regionDetail.dense .regionCard{min-height:108px;padding:12px 21px 12px 26px}.regionDetail.dense .regionCard h3{font-size:21px;margin-bottom:7px}.regionDetail.dense .regionCard p{font-size:18px;line-height:1.35}
.regionCard.regionEmphasis{border-color:#9d7944;box-shadow:0 6px 20px #9d794438}.regionEmphasis::before{content:'';position:absolute;inset:-3px;border:4px solid #b98b39;border-radius:inherit;box-shadow:0 0 0 2px #e9ca8b55,0 0 24px #b3915966,inset 0 0 16px #e9ca8b30;opacity:.7;pointer-events:none;animation:regionAccentBreathe 2.4s ease-in-out infinite;animation-delay:inherit}.regionEmphasis::after{content:'';position:absolute;left:-5px;top:12px;width:7px;height:46px;border-radius:5px;background:#ffe4a4;box-shadow:0 0 12px #d5a545;pointer-events:none;animation:regionAccentTrace 2.4s ease-in-out infinite;animation-delay:inherit}
.regionTitleLine{display:none;animation-delay:inherit}.regionEmphasis h3{position:relative;width:fit-content;max-width:100%;animation-delay:inherit}.regionEmphasis .regionTitleLine{display:block;position:absolute;left:0;right:0;bottom:-6px;height:4px;border-radius:4px;background:#b3915955;overflow:hidden;pointer-events:none}.regionTitleLine::after{content:'';position:absolute;left:0;top:0;bottom:0;width:32%;border-radius:4px;background:linear-gradient(90deg,#b98b3900,#a87522 35%,#e5bb63 75%,#fff0c5);animation:regionTitleLoop 1.8s linear infinite;animation-delay:inherit}
@keyframes regionAccentBreathe{0%,100%{opacity:.6}45%,60%{opacity:1}}@keyframes regionAccentTrace{0%,100%{opacity:.65;transform:translateY(0)}50%{opacity:1;transform:translateY(38px)}}@keyframes regionTitleLoop{from{transform:translateX(-105%)}to{transform:translateX(320%)}}
@media(prefers-reduced-motion:reduce){.regionEmphasis::before,.regionEmphasis::after,.regionTitleLine::after{animation:none;transform:none;opacity:.8}}

`;
const emphasizedRegionTitles = new Set(["File · Tệp và dự án","Terminal · Lệnh và tác vụ","Explorer · File và thư mục","Extensions · Tiện ích","Mở file và Open Editors","Đường dẫn và terminal","Outline · Cấu trúc trong file","Find / Replace trong file","Tab và nhóm editor","Terminal · Chạy lệnh","Nhiều terminal và profile"]);
function regionDetail(s:SlideData){const [label,purpose]=s.visualConcept.split(' | ');return <div className={'regionDetail'+(s.cards.length>6?' dense':'')}><div className="regionLead"><strong>{label}</strong><span>{purpose}</span></div><div className="regionGrid">{s.cards.map((c,i)=><article className={'regionCard'+(label.startsWith('VÙNG 06')||emphasizedRegionTitles.has(c.title)?' regionEmphasis':'')} style={{animationDelay:(-i*.45)+'s'}}><h3>{c.title}<span className="regionTitleLine" aria-hidden="true"/></h3>{c.points?.length?<ul className="regionBullets">{c.points.map(point=><li>{point}</li>)}</ul>:<p>{c.text}</p>}</article>)}</div></div>;}

