function gitStarterInline(s:SlideData){return <div className="gitPractice" data-lesson="12"><style>{practiceCss+starterInlineCss+localRunCss}</style><p className="gitLead">{s.message}</p><div className="starterCards">{s.cards.map((c,i)=><article className="starterCard"><header>{gitGuideMark(i===0?'ZIP':c.logo||'VS Code')}<h2>{c.title}</h2></header><>{c.points?<ul className="starterFiles">{c.points.map(point=>{const [file,label]=point.split(' · ');return <li><code>{file}</code><span>{label}</span></li>;})}</ul>:<p>{c.text}</p>}</><p className="starterNote">{c.detail}</p>{c.link&&<a className="starterDownload gitGuideLink" href={c.link} download="eiu-advertising-starter.zip">{c.linkLabel}<span aria-hidden="true">↓</span></a>}</article>)}</div><div className="practiceFlow">{[['ZIP','Tải project'],['ZIP','Giải nén'],['VS Code','Mở và sẵn sàng chạy']].map(([app,label],i)=><>{i>0&&<i aria-hidden="true">→</i>}<div className="practiceFlowStep">{gitGuideMark(app)}<span>{label}</span></div></>)}</div></div>;}

