function gitLocalRun(s:SlideData){const finish=s.cards[2];return <div className="localRun"><style>{practiceCss+starterInlineCss+localRunCss+localBrowserOptionsCss+localLaunchChoiceCss}</style><p className="gitLead">{localArrowText(s.message)}</p><div className="localRunGrid"><div className="localTerminalSteps">{s.cards.slice(0,2).map((c,i)=><article className="localStep"><header><span className="localStepNumber">{i+1}</span>{gitGuideMark('Node.js')}<h2>{c.title}</h2></header><p>{c.text}</p><div className="localCommand"><code>{c.code}</code>{localCopyButton(c.code||'')}</div><p className="localStepNote">{c.detail}</p></article>)}</div><article className="localBrowser localChoiceBrowser"><header><span className="localStepNumber">3</span><h2>{finish.title}</h2></header><pre className="localReady">{finish.output}</pre><div className="localOpenChoice"><h3>Trình duyệt trên máy</h3><p>{finish.points?.[0]}</p><a className="localOpenApp" href={finish.link} title="Mở http://localhost:3000" target="_blank" rel="noopener noreferrer">{finish.linkLabel}<span aria-hidden="true">↗</span></a></div><div className="localOpenChoice localVsCodeChoice"><h3>{gitGuideMark('VS Code')}Ngay trong VS Code</h3><p>{localArrowText(finish.points?.[1]||'')}</p></div></article></div><div className="localReviewFooter"><p><strong>App đã mở?</strong> {finish.detail}</p><small className="localRunNote">{s.note}</small></div></div>;}


